def _opts(x, n, M):
    o = []
    for ch in x:
        u = M[int(ch)]
        row = []
        for q in range(10):
            v = M[q]
            da, dr = bin(v & ~u).count("1"), bin(u & ~v).count("1")
            if da <= n and dr <= n:
                row.append((q, da, dr))
        o.append(row)
    return o


def _back(o, n, k):
    b = [set() for _ in range(k + 1)]
    b[k] = {(n, n)}
    for i in range(k - 1, -1, -1):
        s = set()
        for q, da, dr in o[i]:
            for a, r in b[i + 1]:
                if a - da >= 0 and r - dr >= 0:
                    s.add((a - da, r - dr))
        b[i] = s
    return b


def _walk(o, b, n, k, i, a, r, acc, rnd):
    """Yield every valid answer, in a random order, pruned by the backward table."""
    if i == k:
        if (a, r) == (n, n):
            yield "".join(acc)
        return
    row = list(o[i])
    rnd.shuffle(row)
    for q, da, dr in row:
        if (a + da, r + dr) in b[i + 1]:
            acc.append(str(q))
            for y in _walk(o, b, n, k, i + 1, a + da, r + dr, acc, rnd):
                yield y
            acc.pop()


def _find(x, n, rnd):
    """One valid answer, drawn at random from all of them ('' if there is none)."""
    M = [63, 6, 91, 79, 102, 109, 125, 7, 127, 111]
    k = len(x)
    o = _opts(x, n, M)
    b = _back(o, n, k)
    if (0, 0) not in b[0]:
        return ""
    for y in _walk(o, b, n, k, 0, 0, 0, [], rnd):
        return y
    return ""


def _no_rearrangement(x, n):
    """True iff no rearrangement of x's own digits is a valid answer.

    Permuting the digits keeps the number of lit segments the same for free, so such an
    instance would reward 'reverse the clue' / 'sort the clue' with no insight at all.
    These instances are dropped here, in the generator, rather than by an extra clause in
    the scorer: the scorer must state exactly the rule the player has to discover, and a
    clause that only ever appears as a rejection is undiscoverable (v2 had one and both
    players called it out as unfair).
    """
    M = [63, 6, 91, 79, 102, 109, 125, 7, 127, 111]
    for p in itertools.permutations(x):
        y = "".join(p)
        if y == x:
            continue
        a = r = 0
        for c, d in zip(x, y):
            u, v = M[int(c)], M[int(d)]
            a += bin(v & ~u).count("1")
            r += bin(u & ~v).count("1")
        if a == n and r == n:
            return False
    return True


def generate(seed):
    r = random.Random(seed)
    while True:
        k = r.choice([3, 4, 4, 5, 5, 5, 6, 6, 6, 6, 6, 6])   # offsets the rejection rate
        n = r.choice([1, 2, 2, 3, 3, 3, 4, 4])
        x = "".join(r.choice("0123456789") for _ in range(k))
        if _no_rearrangement(x, n) and _find(x, n, r):
            return x + "/" + str(n)

